UPDATE vault_credentials
SET display_name = #{params.DisplayName}, metadata = CAST(#{params.Metadata} AS jsonb),
    auth = CAST(#{params.Auth,sensitive=true} AS jsonb),
    secret_payload = CAST(#{params.SecretPayload,sensitive=true} AS jsonb),
    updated_at = #{params.UpdatedAt}
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND vault_external_id = #{params.VaultExternalID}
AND external_id = #{params.CredentialExternalID}
AND deleted_at IS NULL
AND archived_at IS NULL
